function MetricCard({ label, value, change, icon: Icon, down, delay = 0 }: { label: string; value: string; change: string; icon: typeof Activity; down?: boolean; delay?: number }) {
  return <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay }} className="group relative overflow-hidden rounded-2xl border border-coral-100 bg-gradient-to-br from-white via-white to-coral-50/70 p-5 shadow-[0_10px_28px_rgba(37,99,235,.07)] transition hover:-translate-y-0.5 hover:border-coral-200 hover:shadow-[0_16px_36px_rgba(37,99,235,.13)]"><div className="absolute -right-7 -top-8 size-24 rounded-full bg-coral-200/35 blur-2xl"/><div className="relative flex items-start justify-between"><div><p className="text-xs font-semibold text-ink-500">{label}</p><p className="mt-2 text-[26px] font-bold tracking-[-.045em] text-ink-950">{value}</p></div><span className="grid size-10 place-items-center rounded-xl bg-coral-600 text-white shadow-[0_7px_18px_rgba(37,99,235,.22)] transition group-hover:scale-105"><Icon size={18}/></span></div><div className="relative mt-4 flex items-center gap-2 text-xs"><span className={cn("inline-flex items-center gap-0.5 font-bold", down ? "text-rose-600" : "text-coral-700")}>{down ? <ArrowDownRight size={13}/> : <ArrowUpRight size={13}/>} {change}</span><span className="text-ink-400">vs last month</span></div></motion.div>;
}

function CardTitle({ title, subtitle, action }: { title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="flex items-start justify-between gap-3"><div><h2 className="text-sm font-bold tracking-[-.015em] text-ink-950">{title}</h2>{subtitle && <p className="mt-1 text-xs text-ink-400">{subtitle}</p>}</div>{action}</div>; }

function Overview({ goTo }: { goTo: (p: PageId) => void }) {
  return <div className="space-y-5">
    <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.14em] text-coral-600">Friday, May 31</p><h1 className="mt-1 text-2xl font-bold tracking-[-.035em] text-ink-950 sm:text-[28px]">Good morning, Olivia</h1><p className="mt-1 text-[13px] text-ink-500">Here’s the latest across Atelier Supply Co.</p></div><div className="flex items-center gap-2"><Badge tone="green"><span className="size-1.5 rounded-full bg-current"/>All systems healthy</Badge><button className="text-[11px] font-semibold text-ink-500 hover:text-coral-600">Last synced 2 min ago</button></div></div>
    <div className="rounded-2xl border border-coral-200/70 bg-gradient-to-r from-[#f7f2ff] via-white to-[#faf6ff] p-4 sm:flex sm:items-center sm:justify-between"><div className="flex items-start gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-xl bg-coral-500 text-white shadow-sm"><Sparkles size={17}/></div><div><p className="text-sm font-bold text-ink-900">Your store is trending 12% above forecast</p><p className="mt-0.5 text-xs leading-5 text-ink-500">Vellum found 3 opportunities that could add an estimated <b className="text-ink-800">$4,280</b> this month.</p></div></div><button onClick={() => goTo("ai")} className="mt-3 flex shrink-0 items-center gap-1 text-xs font-bold text-coral-600 hover:text-coral-700 sm:mt-0">Review insights <ArrowRight size={14}/></button></div>
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Net revenue" value="$84,240" change="18.2%" icon={CircleDollarSign} delay={.05}/><MetricCard label="Orders" value="1,428" change="12.6%" icon={ShoppingBag} delay={.1}/><MetricCard label="Conversion rate" value="3.82%" change="0.4%" icon={TrendingUp} delay={.15}/><MetricCard label="Avg. order value" value="$126.40" change="2.1%" icon={Banknote} down delay={.2}/></div>
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.65fr)_minmax(300px,.7fr)]">
      <div className="card overflow-hidden p-5 sm:p-6"><CardTitle title="Revenue momentum" subtitle="Actual revenue compared to forecast and prior period" action={<div className="flex items-center gap-3"><span className="hidden items-center gap-1.5 text-[11px] text-ink-500 sm:flex"><i className="size-2 rounded-full bg-[#2563eb]"/>Revenue</span><span className="hidden items-center gap-1.5 text-[11px] text-ink-500 sm:flex"><i className="size-2 rounded-full bg-[#60a5fa]"/>Forecast</span><span className="hidden items-center gap-1.5 text-[11px] text-ink-500 xl:flex"><i className="size-2 rounded-full bg-[#93c5fd]"/>Previous</span><button className="rounded-lg border border-ink-200 px-2.5 py-1.5 text-[11px] font-semibold text-ink-600">30 days</button></div>}/><div className="chart-emphasis mt-5 h-[290px]"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={salesData} margin={{ left: -16, right: 8, top: 8 }}><defs><linearGradient id="revenue" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#2563eb" stopOpacity={.4}/><stop offset="1" stopColor="#60a5fa" stopOpacity={.05}/></linearGradient><linearGradient id="previousRevenue" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#93c5fd" stopOpacity={.34}/><stop offset="1" stopColor="#dbeafe" stopOpacity={.04}/></linearGradient></defs><CartesianGrid stroke="#dbe7f4" vertical={false}/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "#5d7898", fontSize: 11 }} tickMargin={12}/><YAxis axisLine={false} tickLine={false} tick={{ fill: "#5d7898", fontSize: 11 }} tickFormatter={v => `$${v/1000}k`}/><ChartTooltip content={<RevenueTooltip/>}/><Area type="monotone" dataKey="previous" stroke="#93c5fd" strokeWidth={2} fill="url(#previousRevenue)" dot={false}/><Area type="monotone" dataKey="revenue" stroke="#2563eb" strokeWidth={3} fill="url(#revenue)" activeDot={{r:5,fill:"#2563eb",stroke:"#fff",strokeWidth:3}}/><Line type="monotone" dataKey="forecast" stroke="#60a5fa" strokeWidth={2.25} strokeDasharray="5 4" dot={false}/></ComposedChart></ResponsiveContainer></div></div>
      <div className="card p-5 sm:p-6"><CardTitle title="AI opportunity feed" subtitle="Ranked by revenue impact" action={<span className="flex items-center gap-1 text-[10px] font-bold text-emerald-600"><span className="size-1.5 animate-pulse rounded-full bg-emerald-500"/> LIVE</span>}/><div className="mt-4 space-y-1"><InsightRow icon={Tag} color="coral" title="Bundle slow-moving stock" text="Pair Terra Carafe with linen sets" value="+$1.8k"/><InsightRow icon={Users} color="blue" title="Win back 42 customers" text="High intent, no order in 60 days" value="+$1.3k"/><InsightRow icon={TrendingUp} color="green" title="Raise Aurora price 4%" text="Demand sensitivity is currently low" value="+$890"/></div><Button onClick={() => goTo("ai")} variant="outline" className="mt-4 w-full">Open AI studio <ArrowRight size={14}/></Button></div>
    </div>
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.65fr)_minmax(300px,.7fr)]">
      <div className="card overflow-hidden"><div className="p-5 sm:p-6"><CardTitle title="Recent orders" subtitle="12 orders need your attention" action={<button onClick={() => goTo("orders")} className="text-xs font-bold text-ink-600 hover:text-coral-600">View all</button>}/></div><OrderTable compact/></div>
      <div className="card p-5 sm:p-6"><CardTitle title="Channel mix" subtitle="Revenue by sales channel"/><div className="mt-2 h-[220px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{n:"Online",v:68},{n:"Retail",v:21},{n:"Social",v:11}]} dataKey="v" nameKey="n" innerRadius={0} outerRadius={94} paddingAngle={2} stroke="#fff" strokeWidth={4}><Cell fill="#1d4ed8"/><Cell fill="#60a5fa"/><Cell fill="#bfdbfe"/></Pie><ChartTooltip/></PieChart></ResponsiveContainer></div><div className="grid grid-cols-3 gap-2 text-center"><Mix label="Online" value="68%" color="bg-[#1d4ed8]"/><Mix label="Retail" value="21%" color="bg-[#60a5fa]"/><Mix label="Social" value="11%" color="bg-[#bfdbfe]"/></div></div>
    </div>
    <div className="grid gap-5 lg:grid-cols-2">
      <div className="card p-5 sm:p-6"><CardTitle title="Category velocity" subtitle="Units sold by category, current period"/><div className="mt-5 h-[230px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{name:"Home",current:86,previous:62},{name:"Travel",current:74,previous:58},{name:"Textile",current:61,previous:49},{name:"Kitchen",current:53,previous:44},{name:"Decor",current:42,previous:37}]} margin={{left:-18,right:8}}><CartesianGrid stroke="#e2e8f0" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#64748b"}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#64748b"}}/><ChartTooltip/><Bar dataKey="previous" fill="#bfdbfe" radius={[5,5,0,0]} barSize={13}/><Bar dataKey="current" fill="#2563eb" radius={[5,5,0,0]} barSize={13}/></BarChart></ResponsiveContainer></div></div>
      <div className="card p-5 sm:p-6"><CardTitle title="Commerce pulse" subtitle="Five connected operating signals"/><div className="mt-3 h-[245px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={[{axis:"Demand",score:92},{axis:"Margin",score:76},{axis:"Loyalty",score:84},{axis:"Stock",score:71},{axis:"Reach",score:79}]} outerRadius="70%"><PolarGrid stroke="#dbe3ee"/><PolarAngleAxis dataKey="axis" tick={{fontSize:10,fill:"#64748b"}}/><Radar dataKey="score" stroke="#14b8a6" fill="#14b8a6" fillOpacity={.2} strokeWidth={2.5}/><ChartTooltip/></RadarChart></ResponsiveContainer></div></div>
    </div>
  </div>;
}

function RevenueTooltip({ active, payload, label }: { active?: boolean; payload?: Array<{value:number;name:string;color:string}>; label?: string }) { if (!active || !payload) return null; return <div className="rounded-xl border border-ink-200 bg-white/95 p-3 text-xs shadow-xl backdrop-blur"><p className="mb-2 font-bold text-ink-900">{label}</p>{payload.map(p => <div key={p.name} className="flex min-w-32 justify-between gap-4 py-0.5 text-ink-500"><span className="capitalize">{p.name}</span><b className="text-ink-900">${p.value.toLocaleString()}</b></div>)}</div>; }
function Mix({label,value,color}:{label:string;value:string;color:string}) {return <div><div className="mb-1 flex items-center justify-center gap-1.5"><i className={cn("size-2 rounded-full",color)}/><span className="text-[10px] text-ink-500">{label}</span></div><b className="text-sm text-ink-900">{value}</b></div>}
function InsightRow({icon:Icon,color,title,text,value}:{icon:typeof Tag;color:"coral"|"blue"|"green";title:string;text:string;value:string}) { const c={coral:"bg-coral-50 text-coral-600",blue:"bg-sky-50 text-sky-600",green:"bg-emerald-50 text-emerald-600"}[color]; return <button className="group flex w-full items-start gap-3 rounded-xl p-3 text-left transition hover:bg-ink-50"><span className={cn("grid size-8 shrink-0 place-items-center rounded-lg",c)}><Icon size={15}/></span><span className="min-w-0 flex-1"><span className="block text-xs font-bold text-ink-800">{title}</span><span className="mt-0.5 block truncate text-[10px] text-ink-400">{text}</span></span><span className="pt-0.5 text-[11px] font-bold text-emerald-600">{value}</span></button>}

function OrderTable({ compact = false }: { compact?: boolean }) { const rows = compact ? orders.slice(0,4) : orders; return <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead><tr className="border-y border-ink-100 bg-ink-50/60 text-[10px] font-bold uppercase tracking-[.08em] text-ink-400"><th className="px-5 py-3 sm:px-6">Order</th><th className="px-4 py-3">Customer</th><th className="px-4 py-3">Product</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Total</th><th className="w-10"/></tr></thead><tbody>{rows.map(o => <tr key={o.id} className="group border-b border-ink-100 last:border-0 hover:bg-ink-50/50"><td className="px-5 py-3.5 text-xs font-bold text-ink-800 sm:px-6">{o.id}<span className="mt-0.5 block text-[10px] font-normal text-ink-400">{o.date}</span></td><td className="px-4 py-3.5"><div className="flex items-center gap-2"><span className="grid size-7 place-items-center rounded-lg bg-ink-100 text-[9px] font-bold text-ink-600">{o.initials}</span><span className="text-xs font-medium text-ink-700">{o.customer}</span></div></td><td className="px-4 py-3.5 text-xs text-ink-500">{o.product}</td><td className="px-4 py-3.5"><Badge tone={o.tone}><i className="size-1.5 rounded-full bg-current"/>{o.status}</Badge></td><td className="px-4 py-3.5 text-right text-xs font-bold text-ink-900">{o.total}</td><td className="pr-3"><button className="grid size-8 place-items-center rounded-lg text-ink-400 opacity-0 transition hover:bg-ink-100 group-hover:opacity-100"><MoreHorizontal size={16}/></button></td></tr>)}</tbody></table></div> }

function Products({ onAdd }: { onAdd: () => void }) { const [view,setView]=useState<"grid"|"list">("grid"); return <div className="space-y-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2"><div className="flex items-center rounded-xl border border-ink-200 bg-white p-1"><button onClick={()=>setView("grid")} className={cn("rounded-lg px-3 py-1.5 text-xs font-semibold",view==="grid"?"bg-ink-950 text-white":"text-ink-500")}>Grid</button><button onClick={()=>setView("list")} className={cn("rounded-lg px-3 py-1.5 text-xs font-semibold",view==="list"?"bg-ink-950 text-white":"text-ink-500")}>List</button></div><Button variant="outline"><Filter size={15}/> Filter</Button></div><div className="flex gap-2"><Button variant="outline"><Download size={15}/> Export</Button><Button variant="coral" onClick={onAdd}><Plus size={16}/> Add product</Button></div></div>
    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4"><SmallStat label="Active products" value="214" detail="86% of catalog"/><SmallStat label="Low stock" value="8" detail="Needs attention" accent/><SmallStat label="Inventory value" value="$42.8k" detail="Across 4 locations"/><SmallStat label="Sell-through" value="71.4%" detail="Last 30 days"/></div>
    {view==="grid"?<div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{products.map((p,i)=><motion.article initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*.04}} key={p.name} className="group overflow-hidden rounded-2xl border border-ink-200 bg-white shadow-[0_10px_30px_rgba(37,99,235,.09)] transition duration-300 hover:-translate-y-1 hover:border-coral-200 hover:shadow-[0_18px_42px_rgba(37,99,235,.16)]"><div className="relative h-52 overflow-hidden bg-ink-100"><div className="absolute inset-0 bg-cover bg-center transition duration-500 group-hover:scale-[1.05]" style={{backgroundImage:`url(${p.image})`}}/><div className="absolute inset-0 bg-gradient-to-t from-[#0b3b78]/45 via-transparent to-transparent"/><Badge tone={p.status==="Low stock"?"amber":p.status==="Draft"?"neutral":"green"} className="absolute left-3 top-3 bg-white/90 backdrop-blur">{p.status}</Badge><button className="absolute right-3 top-3 grid size-8 place-items-center rounded-lg bg-white/90 text-ink-600 opacity-0 shadow-sm backdrop-blur transition group-hover:opacity-100"><MoreHorizontal size={16}/></button></div><div className="p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-[15px] font-bold text-ink-900">{p.name}</p><p className="mt-1 text-[11px] font-semibold uppercase tracking-wide text-coral-600">{p.category}</p></div><p className="text-[16px] font-extrabold text-coral-700">{p.price}</p></div><p className="mt-3 min-h-10 text-[12px] leading-5 text-ink-500">{p.description}</p><div className="mt-4 grid grid-cols-3 divide-x divide-ink-100 rounded-xl bg-coral-50/60 px-2 py-3 text-center"><span><b className="block text-xs text-ink-900">{p.sales}</b><small className="text-[9px] uppercase text-ink-400">Sold</small></span><span><b className="block text-xs text-ink-900">{p.stock}</b><small className="text-[9px] uppercase text-ink-400">Stock</small></span><span><b className="block text-xs text-ink-900">★ {p.rating}</b><small className="text-[9px] uppercase text-ink-400">Rating</small></span></div></div></motion.article>)}</div>:<div className="card overflow-hidden"><table className="w-full min-w-[700px] text-left"><thead><tr className="border-b border-ink-100 bg-ink-50 text-[11px] uppercase tracking-wider text-ink-400"><th className="px-5 py-3">Product</th><th>Category</th><th>Stock</th><th>Sold</th><th>Status</th><th className="text-right pr-6">Price</th></tr></thead><tbody>{products.map(p=><tr key={p.name} className="border-b border-ink-100 last:border-0 hover:bg-coral-50/30"><td className="flex items-center gap-3 px-5 py-3"><span className="size-11 rounded-lg bg-cover bg-center" style={{backgroundImage:`url(${p.image})`}}/><span><b className="block text-[13px] text-ink-800">{p.name}</b><small className="text-[11px] text-ink-400">{p.description}</small></span></td><td className="text-[13px] text-ink-500">{p.category}</td><td className="text-[13px] text-ink-600">{p.stock}</td><td className="text-[13px] text-ink-600">{p.sales}</td><td><Badge tone={p.status==="Low stock"?"amber":p.status==="Draft"?"neutral":"green"}>{p.status}</Badge></td><td className="pr-6 text-right text-[13px] font-bold">{p.price}</td></tr>)}</tbody></table></div>}
  </div> }

function SmallStat({label,value,detail,accent}:{label:string;value:string;detail:string;accent?:boolean}) {return <div className={cn("card p-4",accent&&"border-amber-200 bg-amber-50/30")}><p className="text-[11px] font-semibold text-ink-500">{label}</p><p className="mt-1 text-xl font-bold tracking-tight text-ink-900">{value}</p><p className={cn("mt-1 text-[10px] text-ink-400",accent&&"text-amber-600")}>{detail}</p></div>}

function Orders() { const [tab,setTab]=useState("All"); return <div className="space-y-5"><div className="grid grid-cols-2 gap-4 xl:grid-cols-4"><SmallStat label="Orders today" value="42" detail="$6,820 revenue"/><SmallStat label="Awaiting fulfillment" value="12" detail="3 are priority" accent/><SmallStat label="In transit" value="38" detail="96% on time"/><SmallStat label="Returns" value="2.4%" detail="Down 0.8%"/></div><div className="card overflow-hidden"><div className="flex flex-col gap-4 border-b border-ink-100 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-1 overflow-x-auto">{["All","Unfulfilled","Processing","Fulfilled","Returns"].map(t=><button key={t} onClick={()=>setTab(t)} className={cn("rounded-lg px-3 py-2 text-xs font-semibold",tab===t?"bg-ink-950 text-white":"text-ink-500 hover:bg-ink-50")}>{t}{t==="Unfulfilled"&&<span className="ml-1.5 text-[9px] opacity-60">12</span>}</button>)}</div><div className="flex gap-2"><Button variant="outline" size="sm"><Filter size={14}/>Filters</Button><Button variant="outline" size="sm"><Download size={14}/>Export</Button></div></div><OrderTable/></div></div> }

function Customers() { return <div className="space-y-5"><div className="grid gap-4 md:grid-cols-3"><div className="card p-5"><p className="text-xs font-semibold text-ink-500">Total customers</p><p className="mt-2 text-2xl font-bold tracking-tight">8,492</p><p className="mt-3 text-xs text-emerald-600"><b>+14.8%</b> this month</p></div><div className="card p-5"><p className="text-xs font-semibold text-ink-500">Repeat purchase rate</p><p className="mt-2 text-2xl font-bold tracking-tight">38.2%</p><p className="mt-3 text-xs text-ink-400">Top 18% of similar stores</p></div><div className="relative overflow-hidden rounded-2xl bg-ink-950 p-5 text-white"><div className="absolute -right-7 -top-10 size-32 rounded-full bg-coral-500/20 blur-2xl"/><div className="relative"><div className="flex items-center gap-2 text-xs font-semibold text-white/65"><Sparkles size={14} className="text-coral-400"/>AI segment</div><p className="mt-2 text-lg font-bold">126 ready to repurchase</p><button className="mt-3 text-xs font-bold text-coral-300">Build campaign →</button></div></div></div><div className="card overflow-hidden"><div className="flex items-center justify-between border-b border-ink-100 p-5"><CardTitle title="Customer directory" subtitle="Updated moments ago"/><Button variant="outline" size="sm"><UserPlus size={14}/> Add customer</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left"><thead><tr className="bg-ink-50 text-[10px] uppercase tracking-wider text-ink-400"><th className="px-5 py-3">Customer</th><th>Segment</th><th>Orders</th><th>Total spent</th><th>Last active</th><th/></tr></thead><tbody>{customers.map(c=><tr key={c.email} className="group border-b border-ink-100 last:border-0 hover:bg-ink-50"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-xl bg-[#ece9e2] text-[10px] font-bold text-ink-600">{c.initials}</span><span><b className="block text-xs text-ink-800">{c.name}</b><small className="text-[10px] text-ink-400">{c.email}</small></span></div></td><td><Badge tone={c.segment==="At risk"?"amber":c.segment==="High value"?"coral":"blue"}>{c.segment}</Badge></td><td className="text-xs text-ink-500">{c.orders}</td><td className="text-xs font-bold text-ink-800">{c.spent}</td><td className="text-xs text-ink-400">{c.last}</td><td><ChevronRight size={15} className="text-ink-300 opacity-0 group-hover:opacity-100"/></td></tr>)}</tbody></table></div></div></div> }

