function GeoInsights() {
  const regions=[{name:"North America",value:46},{name:"Europe",value:28},{name:"Asia Pacific",value:18},{name:"Other",value:8}];
  const sources=[{name:"Organic",value:82,fill:"#2563eb"},{name:"Paid",value:66,fill:"#14b8a6"},{name:"Email",value:54,fill:"#f59e0b"},{name:"Social",value:43,fill:"#f97316"},{name:"Direct",value:35,fill:"#64748b"}];
  return <div className="grid gap-5 lg:grid-cols-2"><div className="card p-5 sm:p-6"><CardTitle title="Revenue by region" subtitle="Share of projected 90-day revenue"/><div className="mt-3 grid items-center gap-4 sm:grid-cols-[1fr_180px]"><div className="h-[230px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={regions} dataKey="value" nameKey="name" outerRadius={90} stroke="#fff" strokeWidth={3}><Cell fill="#2563eb"/><Cell fill="#14b8a6"/><Cell fill="#f59e0b"/><Cell fill="#f97316"/></Pie><ChartTooltip/></PieChart></ResponsiveContainer></div><div className="space-y-3">{regions.map((region,index)=><div key={region.name} className="flex items-center justify-between gap-4 text-[11px]"><span className="flex items-center gap-2 text-ink-500"><i className="size-2.5 rounded-full" style={{background:["#2563eb","#14b8a6","#f59e0b","#f97316"][index]}}/>{region.name}</span><b className="text-ink-900">{region.value}%</b></div>)}</div></div></div><div className="card p-5 sm:p-6"><CardTitle title="Acquisition performance" subtitle="Conversions by traffic source"/><div className="mt-5 h-[245px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={sources} margin={{left:-22,right:6}}><CartesianGrid stroke="#e2e8f0" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#64748b"}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#64748b"}}/><ChartTooltip/><Bar dataKey="value" radius={[6,6,0,0]} barSize={28}>{sources.map(item=><Cell key={item.name} fill={item.fill}/>)}</Bar></BarChart></ResponsiveContainer></div></div></div>;
}
function Health({label,value}:{label:string;value:number}) {return <div><div className="mb-1.5 flex justify-between text-[10px]"><span className="text-blue-100/75">{label}</span><b className="text-white">{value}</b></div><div className="h-1.5 rounded-full bg-white/15"><div className="h-full rounded-full bg-gradient-to-r from-blue-300 to-white shadow-[0_0_8px_rgba(191,219,254,.45)]" style={{width:`${value}%`}}/></div></div>}
function ActionCard({icon:Icon,title,tag,text,impact}:{icon:typeof Gift;title:string;tag:string;text:string;impact:string}) {return <button className="group rounded-2xl border border-ink-200 p-4 text-left transition hover:-translate-y-0.5 hover:border-coral-200 hover:shadow-lg"><div className="flex items-center justify-between"><span className="grid size-9 place-items-center rounded-xl bg-coral-50 text-coral-600"><Icon size={17}/></span><Badge tone="neutral">{tag}</Badge></div><h3 className="mt-4 text-sm font-bold text-ink-900">{title}</h3><p className="mt-2 text-xs leading-5 text-ink-500">{text}</p><div className="mt-4 flex items-center justify-between border-t border-ink-100 pt-3"><b className="text-[11px] text-emerald-600">{impact}</b><ArrowRight size={14} className="text-ink-300 transition group-hover:translate-x-1 group-hover:text-coral-500"/></div></button>}

function Payments() { const paymentData=[{d:"Mon",v:9,fill:"#bfdbfe"},{d:"Tue",v:14,fill:"#93c5fd"},{d:"Wed",v:11,fill:"#60a5fa"},{d:"Thu",v:18,fill:"#3b82f6"},{d:"Fri",v:22,fill:"#2563eb"},{d:"Sat",v:16,fill:"#3b82f6"},{d:"Sun",v:25,fill:"#1d4ed8"}]; return <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Available balance" value="$42,680" change="8.4%" icon={Banknote}/><MetricCard label="Next payout" value="$8,420" change="Jun 3" icon={CreditCard}/><MetricCard label="Gross volume" value="$91,240" change="16.8%" icon={TrendingUp}/><MetricCard label="Refund rate" value="1.8%" change="0.3%" down icon={ArrowDownRight}/></div><div className="grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><div className="relative overflow-hidden rounded-2xl border border-coral-100 bg-gradient-to-br from-white via-white to-coral-50/50 p-6 shadow-[0_12px_32px_rgba(37,99,235,.08)]"><div className="absolute -right-16 -top-20 size-56 rounded-full bg-coral-100/60 blur-3xl"/><div className="relative flex items-start justify-between gap-4"><CardTitle title="Payment volume" subtitle="Successful payments, last 7 days"/><div className="text-right"><b className="block text-lg text-ink-950">$115k</b><span className="text-[10px] font-semibold text-coral-600">+16.8% this week</span></div></div><div className="relative mt-4 h-[285px] rounded-xl border border-coral-100/70 bg-white/70 px-2 pt-4"><ResponsiveContainer width="100%" height="100%"><BarChart data={paymentData} barCategoryGap="14%" margin={{left:-10,right:6,top:8,bottom:2}}><CartesianGrid stroke="#dbe7f4" vertical={false}/><XAxis dataKey="d" axisLine={false} tickLine={false} tick={{fontSize:11,fill:"#5d7898"}} tickMargin={10}/><YAxis axisLine={false} tickLine={false} tickFormatter={v=>`$${v}k`} tick={{fontSize:11,fill:"#5d7898"}}/><ChartTooltip/><Bar dataKey="v" radius={[9,9,3,3]} barSize={52} maxBarSize={58}>{paymentData.map(item=><Cell key={item.d} fill={item.fill}/>)}</Bar></BarChart></ResponsiveContainer></div></div><div className="card p-6"><CardTitle title="Payout account" subtitle="Primary settlement method"/><div className="mt-5 rounded-2xl bg-gradient-to-br from-ink-950 to-ink-800 p-5 text-white shadow-[0_12px_28px_rgba(37,99,235,.2)]"><div className="flex justify-between"><Banknote size={22}/><span className="text-[10px] font-bold tracking-widest text-white/60">VELLUM PAY</span></div><p className="mt-8 text-sm tracking-[.18em]">••••  ••••  ••••  4821</p><div className="mt-5 flex justify-between text-[10px] text-white/60"><span>Mercury Checking</span><span>USD</span></div></div><Button variant="outline" className="mt-4 w-full">Manage payout account</Button></div></div><div className="card overflow-hidden"><div className="p-5"><CardTitle title="Recent transactions" subtitle="All payments and adjustments"/></div><OrderTable compact/></div></div> }

function Automations() { const flows=[{name:"Low stock rescue",desc:"Pause campaigns and alert inventory when stock drops below 8 units.",icon:Boxes,runs:"38 runs",saved:"$2,140 protected",color:"bg-coral-50 text-coral-600"},{name:"VIP welcome journey",desc:"Tag and reward customers when lifetime spend exceeds $1,000.",icon:BadgeCheck,runs:"124 runs",saved:"31% repeat rate",color:"bg-blue-50 text-blue-600"},{name:"Abandoned cart recovery",desc:"Send a personalized sequence four hours after high-intent checkout exits.",icon:ShoppingCart,runs:"286 runs",saved:"$8,620 recovered",color:"bg-sky-50 text-sky-600"}]; return <div className="space-y-5"><div className="relative overflow-hidden rounded-2xl bg-gradient-to-r from-[#082d63] via-[#0b4fa3] to-[#2563eb] p-6 text-white shadow-[0_16px_40px_rgba(37,99,235,.2)]"><div className="absolute -right-12 -top-20 size-64 rounded-full bg-white/15 blur-3xl"/><div className="relative flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2 text-[11px] font-semibold text-blue-100"><Zap size={14}/>AUTOMATION COMMAND CENTER</div><h2 className="mt-2 text-2xl font-bold tracking-tight">Your workflows handled 448 actions this month.</h2><p className="mt-2 text-xs text-blue-100/75">Saving an estimated 18.4 team hours while protecting $10.7k in revenue.</p></div><Button variant="coral" className="shrink-0 border border-white/20 bg-white text-coral-700 hover:bg-blue-50"><Plus size={16}/>New automation</Button></div></div><div className="grid gap-4 lg:grid-cols-3">{flows.map((f,index)=><div key={f.name} className="card group p-5 transition hover:-translate-y-0.5 hover:border-coral-200 hover:shadow-[0_14px_32px_rgba(37,99,235,.11)]"><div className="flex items-center justify-between"><span className={cn("grid size-11 place-items-center rounded-xl",f.color)}><f.icon size={19}/></span><button aria-label={`Toggle ${f.name}`} className="relative h-6 w-11 rounded-full bg-coral-600 shadow-inner"><span className="absolute right-1 top-1 size-4 rounded-full bg-white shadow"/></button></div><div className="mt-5 flex items-center gap-2"><span className="text-[10px] font-bold uppercase tracking-wider text-coral-600">Workflow {index+1}</span><span className="size-1 rounded-full bg-ink-300"/><span className="text-[10px] text-emerald-600">Healthy</span></div><h3 className="mt-2 text-[15px] font-bold text-ink-900">{f.name}</h3><p className="mt-2 min-h-10 text-[12px] leading-5 text-ink-500">{f.desc}</p><div className="mt-5 grid grid-cols-2 gap-3 border-t border-ink-100 pt-4 text-[11px]"><span><small className="block text-[9px] uppercase text-ink-400">Activity</small><b className="mt-1 flex items-center gap-1 text-ink-700"><Activity size={12}/>{f.runs}</b></span><span><small className="block text-[9px] uppercase text-ink-400">Impact</small><b className="mt-1 block text-coral-700">{f.saved}</b></span></div></div>)}</div><div className="card flex flex-col items-center justify-center border-dashed border-coral-200 bg-gradient-to-b from-white to-coral-50/50 p-10 text-center"><span className="grid size-12 place-items-center rounded-2xl bg-coral-100 text-coral-600"><Plus size={20}/></span><h3 className="mt-4 text-sm font-bold text-ink-800">Start with a proven recipe</h3><p className="mt-2 max-w-md text-xs leading-5 text-ink-400">Browse conversion, fulfillment, retention, and customer-care workflows built from real commerce playbooks.</p><Button variant="outline" className="mt-5 border-coral-200 text-coral-700">Browse 24 templates</Button></div></div> }

function SettingsPage() { const [section,setSection]=useState("General"); return <div className="grid gap-5 lg:grid-cols-[210px_1fr]"><div className="card h-fit p-2">{["General","Branding","Team & roles","Notifications","Integrations","Security"].map(s=><button key={s} onClick={()=>setSection(s)} className={cn("flex h-10 w-full items-center rounded-xl px-3 text-xs font-semibold",section===s?"bg-coral-50 text-coral-700 ring-1 ring-coral-200":"text-ink-500 hover:bg-ink-50")}>{s}</button>)}</div><div className="card p-5 sm:p-7"><CardTitle title={section} subtitle="Configure your workspace preferences"/><div className="my-6 h-px bg-ink-100"/><div className="max-w-2xl space-y-5"><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Workspace name</label><input defaultValue="Atelier Supply Co." className="input"/></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Store URL</label><div className="flex rounded-xl border border-ink-200 bg-white focus-within:ring-2 focus-within:ring-coral-500/15"><span className="border-r border-ink-100 px-3 py-2.5 text-xs text-ink-400">vellum.co/</span><input defaultValue="atelier" className="min-w-0 flex-1 bg-transparent px-3 text-sm outline-none"/></div></div><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Time zone</label><button className="input flex items-center justify-between text-left">GMT-04:00 · New York <ChevronDown size={14}/></button></div></div><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Store description</label><textarea rows={4} defaultValue="Curated objects for considered everyday living." className="input resize-none"/></div><div className="rounded-2xl border border-ink-200 p-4"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold text-ink-800">AI weekly brief</p><p className="mt-1 text-[11px] leading-5 text-ink-400">Receive an executive summary of performance, risks, and opportunities every Monday.</p></div><button className="relative h-6 w-11 shrink-0 rounded-full bg-coral-500"><span className="absolute right-1 top-1 size-4 rounded-full bg-white shadow"/></button></div></div><div className="flex justify-end gap-2 pt-2"><Button variant="outline">Discard</Button><Button variant="coral">Save changes</Button></div></div></div></div> }

function AddProductDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (v: boolean) => void }) { const [saved,setSaved]=useState(false); return <Dialog.Root open={open} onOpenChange={v=>{onOpenChange(v);if(!v)setTimeout(()=>setSaved(false),300)}}><Dialog.Portal><Dialog.Overlay className="fixed inset-0 z-50 bg-ink-950/35 backdrop-blur-sm data-[state=open]:animate-in"/><Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-[22px] border border-white/60 bg-white p-6 shadow-2xl focus:outline-none"><Dialog.Close className="absolute right-4 top-4 grid size-8 place-items-center rounded-lg text-ink-400 hover:bg-ink-100"><X size={17}/></Dialog.Close>{saved?<div className="py-10 text-center"><span className="mx-auto grid size-14 place-items-center rounded-full bg-emerald-50 text-emerald-600"><Check size={24}/></span><Dialog.Title className="mt-4 text-xl font-bold text-ink-900">Product added</Dialog.Title><Dialog.Description className="mt-2 text-sm text-ink-500">Your draft is ready to refine and publish.</Dialog.Description><Button className="mt-6" onClick={()=>onOpenChange(false)}>Back to catalog</Button></div>:<><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-coral-50 text-coral-600"><Package size={18}/></span><div><Dialog.Title className="text-lg font-bold text-ink-900">Add a new product</Dialog.Title><Dialog.Description className="text-xs text-ink-400">Create a polished listing in a few steps.</Dialog.Description></div></div><div className="mt-6 space-y-4"><button className="flex h-28 w-full flex-col items-center justify-center rounded-2xl border border-dashed border-ink-300 bg-ink-50/50 text-ink-400 transition hover:border-coral-300 hover:bg-coral-50/40 hover:text-coral-600"><Upload size={20}/><span className="mt-2 text-xs font-semibold">Drop images or click to upload</span></button><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Product title</label><input className="input" placeholder="e.g. Cove Ceramic Vase"/></div><div className="grid grid-cols-2 gap-3"><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Price</label><input className="input" placeholder="$0.00"/></div><div className="grid gap-2"><label className="text-xs font-bold text-ink-700">Category</label><button className="input flex items-center justify-between">Select <ChevronDown size={14}/></button></div></div><button className="flex items-center gap-2 text-xs font-bold text-coral-600"><WandSparkles size={14}/>Generate description with AI</button></div><div className="mt-6 flex justify-end gap-2"><Dialog.Close asChild><Button variant="outline">Cancel</Button></Dialog.Close><Button variant="coral" onClick={()=>setSaved(true)}>Save as draft</Button></div></>}</Dialog.Content></Dialog.Portal></Dialog.Root> }

